import AppKit

/// The Color sub-tab's last section, **Look** (spec §11 GR-7 [b], grading
/// GR5b): the gallery of the eight built-in looks and None, the
/// imported LUTs and Import LUT… (GR-8 [b], GR6b), and an Amount row when
/// every selected clip has a look.
///
/// A tile (a LUT's too), None and Reset write the clips' OWN look in one
/// `set_video`, even with an action selected (GR-7 [b] (1)): in an action's
/// end `look: null` only stops animating the look, so it could not remove
/// one, and the kind switches at the end anyway. The Amount row is the one
/// that animates: it goes through `binding.ops(video:)` like every number.
extension VideoPane {
    // MARK: Look

    /// Every selected clip that draws has a look (evaluated, as the rows
    /// read); false for no such clip. `ClipPane`'s structure signature reads
    /// it, since it adds or removes the Amount row.
    var allLooked: Bool {
        let clips = binding.videoClips
        return !clips.isEmpty && clips.allSatisfy { binding.video($0).look != nil }
    }

    /// Some selected clip's look is a LUT and its source file is converted
    /// by Camera Log (spec §11 GR-16): a camera LUT applied as a look would
    /// then convert it twice. `ClipPane`'s structure signature reads it, since
    /// it adds or removes the warning row.
    var lutOverCameraLog: Bool {
        let snapshot = binding.snapshot
        return binding.videoClips.contains { clip in
            guard binding.video(clip).look?.kind == .lut,
                let media = clip.source.mediaID, snapshot.media(media)?.color != nil
            else { return false }
            return true
        }
    }

    /// Some selected clip's look is a LUT and the project is HDR (HLG), where
    /// a `.cube` LUT still reads its values as Rec. 709 (spec §11 HD-2, HD-13
    /// (k)). `ClipPane`'s structure signature reads it, since it adds or
    /// removes the warning row.
    var lutInHLG: Bool {
        binding.snapshot.canvas.output == .hlg
            && binding.videoClips.contains { binding.video($0).look?.kind == .lut }
    }

    func lookSection(_ gallery: LookGallery) -> InspectorSection {
        let binding = self.binding
        func ids() -> [UInt32] { binding.videoClips.map(\.id) }
        func looks() -> [LookProps?] { binding.videoClips.map { binding.video($0).look } }
        func names() -> [UInt32: String] {
            var names: [UInt32: String] = [:]
            for lut in LookGallery.luts(in: binding.snapshot) {
                names[lut.id] = LookGallery.lutName(lut)
            }
            return names
        }
        let view = LookGalleryView(
            gallery: gallery, binding: binding,
            onPick: { binding.apply("Look", [LookGallery.op($0, clips: ids())]) },
            onPickLUT: { binding.apply("Look", [LookGallery.op(lut: $0, clips: ids())]) },
            onImport: { [weak self] in
                self?.inspector?.onCommand?(#selector(EditorViewController.importLUT(_:)))
            })
        var rows: [NSView] = [view]
        if lutOverCameraLog {
            // A warning only: a creative LUT there is legitimate (GR-16).
            let warning = InspectorRowLabel(
                "This clip's file is converted by Camera Log; a camera LUT here converts it "
                    + "twice.")
            warning.lineBreakMode = .byWordWrapping
            warning.maximumNumberOfLines = 0
            rows.append(inspectorRow(nil, [warning]))
        }
        if lutInHLG {
            // A warning only, as GR-16's: a LUT keeps its 0…1 meaning.
            let warning = InspectorRowLabel(
                "This project is HDR (HLG): a .cube LUT reads its values as Rec. 709.")
            warning.lineBreakMode = .byWordWrapping
            warning.maximumNumberOfLines = 0
            rows.append(inspectorRow(nil, [warning]))
        }
        rows += allLooked ? [
            inspectorValueRow(
                "Amount", binding, name: "Amount", unit: "%", decimals: 0, min: 0, max: 100,
                quick: [0, 25, 50, 75, 100],
                read: { (binding.videoProps.look?.amount ?? 1) * 100 },
                ops: { binding.ops(video: VideoPatch(look: .some(LookPatch(amount: $0 / 100)))) },
                mixed: { binding.mixedVideo { $0.look?.amount } }),
        ] : []
        return InspectorSection(
            id: "video.look", title: "Look",
            summary: { LookGallery.summary(looks(), names: names()) },
            reset: { binding.apply("Look", [LookGallery.op(nil, clips: ids())]) },
            differs: { looks().contains { $0 != nil } },
            defaultExpanded: false,
            rows: rows)
    }
}
import AppKit

/// The Look section's gallery model (spec §11 GR-7 [b], grading GR5b):
/// which clips a look applies to, the op a tile or a menu item sends,
/// and the nine thumbnails — None and the eight — each the composited frame
/// with that tile's click applied, then one per imported `.cube` LUT (spec
/// §11 GR-8 [b]), in the media list's order.
///
/// **It lives on `ClipPane`, not on the view**, because the pane rebuilds its
/// sections on every structure change and a thumbnail set that died with each
/// build would re-render for nothing. A view attaches itself (`view`) when it
/// is built, and an update from any other view — a retired build's late
/// `viewDidMoveToWindow` — is ignored.
///
/// **When it renders.** Its inputs are the edited project's HANDLE, the target
/// ids and the thumbnail time. An update or a playhead poke with the inputs it
/// last scheduled does nothing; anything else re-arms one `settle` timer, so a
/// playhead moving every frame (playback, a scrub) never renders. The timer
/// renders only if the gallery is open then (its section expanded, its window
/// there); hiding it or leaving the window cancels the timer and supersedes a
/// running generation. A generation applies the trial ops (the nine, then one
/// per LUT) on main and renders them off main, one tile after another, through
/// `Exporter.renderFrame` — `render_frame`'s renderer, so a thumbnail is the
/// pixels that tool writes (its file carries PR-11's label; a tile's dump is
/// unlabelled, spec §11 PR-11) —
/// with `RecipeOptions.none` (thumbnails ignore Show Ungraded, as an export
/// does). A superseded generation skips its remaining tiles, and its results
/// never land.
final class LookGallery {
    /// None, then the eight in the core's order: the gallery's reading order.
    static let tiles: [LookKind?] = [nil] + LookKind.builtIns.map { Optional($0) }
    static let thumbnailWidth = 256
    static let settle: TimeInterval = 0.3
    #if FRAMEJOB_DEV_TOOLS
    /// A launch default naming a folder: each completed generation N writes
    /// `<folder>/<N>/<tile>.png` and then `<folder>/<N>/manifest.json`.
    static let dumpKey = "RCDevLookGalleryDump"
    #endif

    private(set) var thumbnails: [CGImage?] = Array(repeating: nil, count: tiles.count)
    /// The Imported group's thumbnails, by the LUT's media id.
    private(set) var lutThumbnails: [UInt32: CGImage] = [:]
    /// The attached view; an update from any other is ignored.
    weak var view: LookGalleryView?

    private struct Inputs {
        let project: ReelProject
        let ids: [UInt32]
        let time: Ticks

        func same(_ other: Inputs?) -> Bool {
            guard let other else { return false }
            return project === other.project && ids == other.ids && time == other.time
        }
    }

    /// A generation's cancel flag, read off main between tiles.
    private final class Token {
        private let lock = NSLock()
        private var cancelled = false

    /// The clips a look applies to: those that draw and take a grade —
    /// source pixels of their own, or an adjustment clip.
    static func targets(_ clips: [ClipSnapshot], in snapshot: ProjectSnapshot) -> [ClipSnapshot] {
        clips.filter {
            InspectorTab.hasPixels($0, in: snapshot)
                && (InspectorTab.hasSourcePixels($0, in: snapshot) || InspectorTab.isAdjustment($0))
        }
    }

    /// What a tile or a menu item sends: the kind alone, so each clip keeps
    /// its amount (1 on a clip with none), or `look: null` for None.
    static func op(_ kind: LookKind?, clips: [UInt32]) -> ReelOp {
        .setVideo(clips: clips, patch: VideoPatch(look: .some(kind.map { LookPatch(kind: $0) })))
    }

    /// What a LUT's tile or menu item sends: `{kind: lut, media}`, no amount.
    static func op(lut media: UInt32, clips: [UInt32]) -> ReelOp {
        .setVideo(clips: clips, patch: VideoPatch(look: .some(LookPatch(kind: .lut, media: media))))
    }

    /// The project's `.cube` LUTs, in the media list's order (GR-8 [b]).
    static func luts(in snapshot: ProjectSnapshot) -> [MediaSnapshot] {
        snapshot.media.filter { $0.kind == .lut }
    }

    /// A LUT's tile and item title: its name less a trailing `.cube`.
    static func lutName(_ media: MediaSnapshot) -> String {
        let name = media.name
        return name.lowercased().hasSuffix(".cube") ? String(name.dropLast(5)) : name
    }

    /// The thumbnail time: the playhead inside the first clip, else its first
    /// frame.
    static func time(first: ClipSnapshot, playhead: Ticks) -> Ticks {
        first.start <= playhead && playhead < first.end ? playhead : first.start
    }

    /// `.some(kind)` when every look is that kind, `.some(nil)` when none has
    /// a look, nil when they disagree or there are none.
    static func shared(_ looks: [LookProps?]) -> LookKind?? {
        guard let first = looks.first else { return nil }
        let kind = first?.kind
        return looks.allSatisfy({ $0?.kind == kind }) ? .some(kind) : nil
    }

    /// "Warm 80%" when kind, LUT and amount are shared (a LUT by `names`,
    /// "LUT" when it has none), "none" when no clip has a look, "mixed"
    /// otherwise.
    static func summary(_ looks: [LookProps?], names: [UInt32: String] = [:]) -> String {
        guard let first = looks.first else { return "none" }
        guard looks.allSatisfy({ $0 == first }) else { return "mixed" }
        guard let look = first else { return "none" }
        let name = look.kind == .lut ? look.media.flatMap { names[$0] } ?? "LUT"
            : look.kind.displayName
        return name + String(format: " %.0f%%", look.amount * 100)
    }
}
            document.applyEdit("Look", [LookGallery.op(lut: lut, clips: targets.map(\.id))])
        } else if let kind = lookKind(tag) {
            document.applyEdit("Look", [LookGallery.op(kind, clips: targets.map(\.id))])
        } else {
            NSSound.beep()
        }
    }

    /// Import LUT…: a `.cube` chosen in a sheet panel, then
    /// `importLUT(from:into:clips:)` for the clips selected now.
    @objc func importLUT(_ sender: Any?) {
        let targets = lookTargets.map(\.id)
        guard let document = document, let window = view.window, !targets.isEmpty else {
            NSSound.beep()
            return
        }
        let panel = NSOpenPanel()
        panel.allowsMultipleSelection = false
        panel.canChooseDirectories = false
        panel.allowedContentTypes = [MediaImporter.lutType]
        panel.message = "Choose a .cube LUT to apply to the selected clips."
        panel.beginSheetModal(for: window) { [weak self] response in
            guard response == .OK, let url = panel.url else { return }
            self?.importLUT(from: url, into: document, clips: targets)
        }
    }

    /// The probe, then ONE undo step "Import LUT": `add_media` and the look,
    /// the id learned as Add Background ▸ Image… learns it
    /// (`backgroundMedia(for:in:)`: the id `add_media` mints, or the row a
    /// file already in the list holds). Off-event, so grouped explicitly. A
    /// refused file is the document's error sheet and changes nothing.
    func importLUT(from url: URL, into document: ProjectDocument, clips: [UInt32]) {
        MediaImporter.probe(url: url, mayAsk: true) { result in
            do {
                let descriptor = try result.get()
                let add = ReelOp.addMedia(descriptor: descriptor)
                guard let id = try Self.backgroundMedia(for: descriptor, in: document.project)
                else {
                    NSSound.beep()
                    return
                }
                let look = LookGallery.op(lut: id, clips: clips)
                document.performGroupedEdit("Import LUT", [add, look])
            } catch {
                document.present(error)
            }
        }
    }

    /// What a tag SAYS: `.some(kind)` for an index into the vocabulary,
    /// `.some(nil)` for None, nil for a tag no builder writes.
    private func lookKind(_ tag: Int) -> LookKind?? {
        if tag == Self.lookNoneTag { return .some(nil) }
        return LookKind.builtIns.indices.contains(tag) ? .some(LookKind.builtIns[tag]) : nil
    }

    // MARK: - Validation

    /// The half of `validateUserInterfaceItem` this file owns; nil is "not
    /// mine". An item is on when every target's OWN look is its kind (None:
    /// no look; a LUT's item: that LUT), dashed when some but not all are
    /// (GR-7 [b] (3)), off otherwise; enabled exactly when there is a target.
    func validateLookAction(_ action: Selector, item: any NSValidatedUserInterfaceItem) -> Bool? {
        guard action == #selector(setLook(_:)) else { return nil }
        let targets = lookTargets
        let menuItem = item as? NSMenuItem
        if menuItem?.tag == Self.lookLUTTag {
            let lut = (menuItem?.representedObject as? NSNumber)?.uint32Value
            let carrying = targets.filter {
                $0.videoProps.look?.kind == .lut && $0.videoProps.look?.media == lut
            return true
        }
        return image
    }
}

/// Clip ▸ Look ▸'s LUT rows (spec §11 GR-8 [b]): between the eight's separator
/// and None, the project's `.cube` LUTs in media-list order, tag −2 with the
/// media id as `representedObject`, then a second separator — none of either
/// with no LUT. Rewritten each time the menu opens (`menuNeedsUpdate`), for
/// the main window's project; `UIMenu.fillDynamic` asks it for a named window.
final class LookMenuFiller: NSObject, NSMenuDelegate {
    static let shared = LookMenuFiller()

    func menuNeedsUpdate(_ menu: NSMenu) {
        fill(menu, for: NSApp.mainWindow)
    }

    func fill(_ menu: NSMenu, for window: NSWindow?) {
        let document = window?.windowController?.document as? ProjectDocument
        Self.fill(menu, luts: document.map { LookGallery.luts(in: $0.project.snapshot) } ?? [])
    }

    static func fill(_ menu: NSMenu, luts: [MediaSnapshot]) {
        guard let first = menu.items.firstIndex(where: \.isSeparatorItem) else { return }
        while menu.items.count > first + 2 { menu.removeItem(at: first + 1) }
        var at = first + 1
        for lut in luts {
            let item = NSMenuItem(
                title: LookGallery.lutName(lut),
                action: #selector(EditorViewController.setLook(_:)), keyEquivalent: "")
            item.tag = EditorViewController.lookLUTTag
            item.representedObject = NSNumber(value: lut.id)
            menu.insertItem(item, at: at)
            at += 1
        }
        if at > first + 1 { menu.insertItem(.separator(), at: at) }
    }
}

/// Clip ▸ Switch Angle ▸'s rows (spec §11 SW-15 (a)), rewritten each time the
/// menu opens for the main window's editor; `UIMenu.fillDynamic` asks it for
/// a named window. One row per `SwitchAngle.angles` of the ONE selected clip —
/// the track's title, its index as the tag, the track id as
/// `representedObject` — else the single `placeholder()`.
final class SwitchAngleMenuFiller: NSObject, NSMenuDelegate {

//! The look vocabulary (spec §11 GR-7, format 15):
//! [`Look`], the `video.look` a clip carries — one of the eight built-in
//! [`LookKind`]s or an imported `.cube` LUT (`lut`, GR-8, naming its media),
//! and how much of it — and each built-in kind's [`LookDefinition`], the
//! DATA the compositor bakes.
//!
//! **Rust decides, Metal does** (spec §7): a look is defined here, as Color's
//! four keys, Light's nine and a [`SplitTone`], and published in the recipe
//! as that definition; the app bakes it on the GPU into a 33³ lattice with
//! the layer stage's own functions and mixes it at step 4d. Nothing here is
//! a colour table: the eight are Frame Job's own first numbers (tuned by the
//! owner at GR7), built from the textbook operations tone already uses — the
//! Concat rule (`designs/adr/effects-survey.md`) stands.
//!
//! Re-exported whole by `model_props.rs`, which `model.rs` re-exports whole
//! in turn, so `crate::model::Look` resolves like every other property type.
//!
//! **The declaration ORDER of [`LookKind`] is the gallery's and the menu's**
//! (GR-7): append, never reorder; `Lut` comes last and is not one of
//! [`LookKind::BUILT_IN`]. The JSON spelling of each variant is persisted, so
//! a rename needs a migration step. Closed: a misspelt kind is refused at the
//! serde boundary naming the nine, because there is no neutral look to fall
//! back to — "no look" is `video.look` absent. What `media` must name, and
//! when, is `lut.rs`'s.

use serde::{Deserialize, Serialize};

use crate::model::ColorAdjust;

/// The amount a look takes when a patch names only its kind: all of it
/// (GR-7 choice 2).
pub const LOOK_DEFAULT_AMOUNT: f64 = 1.0;

fn default_look_amount() -> f64 {
    LOOK_DEFAULT_AMOUNT
}

/// The eight built-in looks, in the gallery's order (GR-7 choice 1), and
/// `Lut`, an imported `.cube` file (GR-8), whose table is the media's.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum LookKind {
    Warm,
    Cool,
    TealOrange,
    Vivid,
    Faded,
    Vintage,
    Dramatic,
    BlackWhite,
    Lut,
}

/// A clip's look: which, and how much (0…1, `props_check.rs` refuses
/// outside it). `kind` has NO default, so a `look` without one does not read
/// — a patch naming only an amount on a clip that has no look is refused,
/// and an action's end that does so evaluates as no look (`actions.rs`).
/// `media` is the LUT's media id, with `Lut` only (GR-8; `lut.rs` holds the
/// rule), written between `kind` and `amount` and only when set.
#[derive(Debug, Clone, Copy, PartialEq, Serialize, Deserialize)]
pub struct Look {
    pub kind: LookKind,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub media: Option<u32>,
    #[serde(default = "default_look_amount")]
    pub amount: f64,
}

/// Two hues pushed into the shadows and the highlights, the one building
/// block a look has that Light does not (GR-7 choice 4). Hues in degrees,
/// amounts 0…1; the bake weights each by (1 − Y)² and Y², Y the luma.
#[derive(Debug, Clone, Copy, Default, PartialEq, Serialize)]
pub struct SplitTone {
    pub shadow_hue: f64,
    pub shadow_amount: f64,
    pub highlight_hue: f64,
    pub highlight_amount: f64,
}

/// What a look IS: the colour, tone and split tone its lattice is baked
/// from. Published in the recipe under the layer's `look` key.
#[derive(Debug, Clone, Copy, Default, PartialEq, Serialize)]
pub struct LookDefinition {
    pub color: ColorAdjust,
    pub split: SplitTone,
}

impl LookKind {
    /// The eight built-in kinds, in declaration order (`Lut` is not one).
    pub const BUILT_IN: [LookKind; 8] = [
        LookKind::Warm,
        LookKind::Cool,
        LookKind::TealOrange,
        LookKind::Vivid,
        LookKind::Faded,
        LookKind::Vintage,
        LookKind::Dramatic,
        LookKind::BlackWhite,
    ];

    /// The kind's definition — GR-7's table, every unlisted value 0; `None`
    /// for `Lut`, whose table is a file's.
    pub fn definition(self) -> Option<LookDefinition> {
        let neutral = ColorAdjust::default();
        let none = SplitTone::default();
        let (color, split) = match self {
            LookKind::Lut => return None,
            LookKind::Warm => (
                ColorAdjust {
                    temperature: 0.35,
                    tint: 0.05,
                    vibrance: 0.10,
                    ..neutral
                },
                SplitTone {
                    highlight_hue: 40.0,
                    highlight_amount: 0.25,
                    ..none
                },
            ),
            LookKind::Cool => (
                ColorAdjust {
                    temperature: -0.35,
                    contrast: 0.05,
                    ..neutral
                },
                SplitTone {
                    shadow_hue: 215.0,
                    shadow_amount: 0.30,
                    ..none
//! `.cube` LUTs as media and as looks (spec §11 GR-8): the rules a `lut`
//! media row and a `video.look {kind: "lut", media}` obey, written once for
//! every door that meets them.
//!
//! - **The row.** A LUT is media so it is referenced, relinked and
//!   consolidated like footage, but it has no picture of its own: its row
//!   carries no video, audio, alpha or duration ([`check_lut_fields`], which
//!   `edit_track.rs`'s `check_media_fields` calls for `add_media`, a
//!   relink's probe and a pasted media row), and it is never placed as a clip — `add_clip`,
//!   `insert_clip`, `overwrite_clip` and `add_background` answer
//!   [`lut_not_placeable`].
//! - **The look.** `media` is required with `lut` and goes with nothing
//!   else, and must name a `lut` media of the project
//!   ([`Project::check_look_media`], beside `check_adjustment_video` on the
//!   patch path and on every pasted group, and in `validate` for a file),
//!   through [`Project::check_lut_reference`], which `media_color.rs`'s
//!   `color.lut` shares. A
//!   patch naming a built-in kind and no `media` drops a stored one
//!   ([`normalise_look`]), so a built-in kind on a LUT clip replaces the LUT.
//! - **An action's end** is never checked against the media list
//!   (`set_action_end` checks shape only), so an end may name a LUT that is
//!   not there: the evaluator reads such a look as NO look
//!   ([`Project::evaluates_as_look`]), and `actions.rs` switches `media` at
//!   the end like a `kind`, so an id is never interpolated.
//! - **Removing a used LUT** ([`Project::remove_lut`]) refuses naming the
//!   clips whose base look it is and the media whose Camera Log it is (spec
//!   §11 GR-16, `media.color.lut`), or with `with_clips` clears those looks
//!   and conversions and keeps the clips and the media; ends are left alone
//!   (inert by the evaluator).
//! - **Paste** brings a LUT's row by path like any media; an id the payload
//!   does not carry becomes no look ([`remap_look_media`]) rather than
//!   another media's id.

use std::collections::HashMap;

use serde_json::Value;

use crate::export_overrides::spelled;
use crate::model::{Clip, Look, LookKind, Media, MediaKind, Project, VideoProps};
use crate::outcome::Outcome;

/// The refusal for `media` on a built-in kind.
fn media_goes_with_lut(kind: LookKind) -> String {
    format!("video.look.media goes with kind lut, not {}", spelled(kind))
}

/// What `add_clip` and the other placing ops answer for a LUT: it is a look,
/// and the sentence says how to apply one.
pub(crate) fn lut_not_placeable(media: u32) -> String {
    format!(
        "media {media} is a LUT: apply it as a look (set_video {{look: {{kind: \"lut\", \
         media: {media}}}}}), it is not placed as a clip"
    )
}

/// A `lut` row's own check: it has no picture or sound, so none of the
/// flags or a duration. Any other kind passes.
pub(crate) fn check_lut_fields(media: &Media) -> Result<(), String> {
    if media.kind == MediaKind::Lut
        && (media.has_video || media.has_audio || media.has_alpha || media.duration != 0)
    {
        return Err("a lut media has no video, audio, alpha or duration".to_string());
    }
    Ok(())
}

/// After a video patch has merged: a patch that names a built-in `kind` and
/// no `media` drops a stored `media` (the built-in replaces the LUT), and a
/// patch that names `media` on a built-in kind is refused.
pub(crate) fn normalise_look(props: &mut VideoProps, patch: &Value) -> Result<(), String> {
    let Some(Value::Object(asked)) = patch.get("look") else {
        return Ok(());
    };
    let Some(look) = props.look.as_mut() else {
        return Ok(());
    };
    if look.kind == LookKind::Lut {
        return Ok(());
    }
    let names_media = asked.get("media").is_some_and(|media| !media.is_null());
    if names_media {
        return Err(media_goes_with_lut(look.kind));
    }
    if asked.get("kind").is_some_and(|kind| !kind.is_null()) {
        look.media = None;
    }
    Ok(())
}

/// The LUT a clip's base look names, if it is a LUT look.
        + "clip's first and last frame, during is {kind: "
        + "\(duringNames.joined(separator: "|")), amount: 0–1, period: ticks} over the "
        + "whole clip and drift ignores its period. Like every other object here it "
        + "MERGES: a slot you leave out keeps what is stored, a slot set to null clears "
        + "that slot, {motion: null} clears the whole preset, and a motion with no slot "
        + "left reads back as null. The two durations are snapped to the document's "
        + "frame grid and the period is snapped with a floor of ONE frame (it divides "
        + "in every during formula and has no zero), so get_project can answer with a "
        + "tick count near the one you sent rather than the one itself. "
        + "in + out longer than the clip scales both down to "
        + "meet rather than refusing. It is NOT an animation target — set_action_end "
        + "refuses it — and get_project reports the clip UN-MOVED, since the preset "
        + "becomes placement only when a frame is rendered)"
    // `video.look`'s clause (spec §11 GR-7), its own explicitly-typed local
